const format = function refundMessage({ body }) {
  const escape = (text) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  if (!Number.isSafeInteger(body.id) || body.id < 1) throw new Error('WooCommerce order ID is missing or invalid');
  for (const field of ['status', 'total', 'currency', 'date_modified']) if (typeof body[field] !== 'string') throw new Error('WooCommerce order is missing ' + field);
  const money = typeof body.currency_symbol === 'string' && body.currency_symbol ? body.currency_symbol + body.total : body.currency + ' ' + body.total;
  const footer = '*Order updated:* ' + escape(body.date_modified);
  if (footer.length > 300) throw new Error('Order timestamp exceeds Slack footer size');
  const text = ':x: A refund has been issued :x:';
  return { text, attachments: [{ color: '#FF0000', fallback: text, fields: [
    { title: 'Order ID', value: String(body.id), short: true },
    { title: 'Status', value: escape(body.status), short: true },
    { title: 'Total', value: escape(money), short: true },
  ], footer }] };
}

return {json:format({body:$json.body})};

const read = function orderAmount({ body }) {
  if (typeof body.total !== 'string' || !/^\d+(?:\.\d+)?$/.test(body.total) || !Number.isFinite(Number(body.total))) throw new Error('WooCommerce order total must be a nonnegative decimal string');
  if (typeof body.status !== 'string' || !body.status) throw new Error('WooCommerce order status is missing');
  return { total: Number(body.total), status: body.status };
}

return {json:{body:$json,...read({body:$json})}};
